#!/usr/bin/env bash
# backup-usb.sh - second copy on a USB disk (USB_BACKUP_DIR)
#
# Runs as root at 03:50 (cron.d-decolab-root), after backup.sh and its check.
# Copies, onto a disk that can be unplugged and kept elsewhere:
#   daily/    the nightly backups of BACKUP_DIR, kept USB_KEEP (90) by count
#   immich/   Immich's originals: upload/, library/, profile/ (thumbnails and
#             transcoded videos are regenerated by Immich)
#   nas/      the Samba share DATA_DIR/nas
# immich/ and nas/ are mirrors (rsync --delete), but nothing is lost at
# once: every file a run deletes or overwrites on the disk is moved to
# deleted/<date>/ and kept USB_DELETED_KEEP_DAYS (30) days. A file deleted
# by mistake, or overwritten by ransomware, can be fetched from there.
#
# Safety, before anything is written:
#   - USB_BACKUP_DIR must hold the marker file .decolab-usb-backup: an
#     unplugged disk leaves an empty mount point, and the copy would fill
#     the system disk instead (or a different disk would be overwritten)
#   - it must be on another file system than BACKUP_DIR
#   - an EMPTY source never touches a non-empty mirror: with --delete it
#     would wipe the copy you may be about to restore from
#
# Off (exits quietly) while USB_BACKUP_DIR is empty.
set -uo pipefail
# shellcheck source-path=SCRIPTDIR/..
# shellcheck source=lib/common.sh
. "$(cd "$(dirname "$0")/.." && pwd)/lib/common.sh"
decolab_init

if [ -z "${USB_BACKUP_DIR:-}" ]; then
  log "USB copy is off (USB_BACKUP_DIR empty)"
  exit 0
fi
usb=$USB_BACKUP_DIR
keep=${USB_KEEP:-90}
deleted_keep=${USB_DELETED_KEEP_DAYS:-30}
stamp=$(date +%Y-%m-%d_%H-%M)

errors=""
err() {
  errors="$errors- $1
"
  log "ERROR: $1"
}
finish() {
  if [ -z "$errors" ]; then
    kuma_push USB up "$1" || exit 1
    log "OK: $1"
    exit 0
  fi
  notify "🔴 USB copy" "$errors"
  kuma_push USB down "$(printf '%s' "$errors" | tr '\n' ' ')"
  log "FAILED: $(printf '%s' "$errors" | tr '\n' ' ')"
  exit 1
}
stop() { # stop REASON - nothing was written
  err "$1"
  finish ""
}

# dev_of PATH - file system of PATH, or of its nearest existing parent
dev_of() {
  python3 -I -c 'import os, sys
p = os.path.abspath(sys.argv[1])
while not os.path.exists(p):
    p = os.path.dirname(p)
print(os.stat(p).st_dev)' "$1"
}
[ -f "$usb/.decolab-usb-backup" ] ||
  stop "$usb/.decolab-usb-backup is missing: disk not plugged in or not mounted? Nothing copied."
# DECOLAB_TEST_SAME_DEVICE: tests only, their directories share one disk
if [ "${DECOLAB_TEST_SAME_DEVICE:-0}" != 1 ]; then
  for other in "$BACKUP_DIR" "$DATA_DIR"; do
    [ "$(dev_of "$usb")" != "$(dev_of "$other")" ] ||
      stop "$usb is on the same file system as $other: that is no second copy. Nothing copied."
  done
fi
job_lock "${BACKUP_LOCK_WAIT_S:-1800}" || stop "another heavy job held the lock for too long"

# 1. the nightly backups (no --delete: the disk keeps a longer history)
if [ -d "$BACKUP_DIR" ]; then
  rsync -a --exclude='.partial-*' "$BACKUP_DIR/" "$usb/daily/" || err "daily: rsync ended with $?"
  pattern=$DECOLAB_BACKUP_PATTERN
  complete=$(find "$usb/daily" -mindepth 1 -maxdepth 1 -type d -name "$pattern" | sort)
  n=$(printf '%s' "$complete" | grep -c . || true)
  if [ "${n:-0}" -gt "$keep" ]; then
    printf '%s\n' "$complete" | head -n $((n - keep)) | while IFS= read -r d; do rm -rf "$d"; done
  fi
  find "$usb/daily" -mindepth 1 -maxdepth 1 -type d -name "$pattern-incomplete" -mtime +"$keep" -exec rm -rf {} + 2>/dev/null
else
  err "daily: $BACKUP_DIR is missing"
fi

# mirror NAME SRC DST - SRC/ to DST/, deleted and overwritten files kept
mirror() {
  local name=$1 src=$2 dst=$3
  # rsync follows "$src/": a container that swapped its folder for a link
  # would have root copy any host directory onto the disk
  if [ -L "$src" ]; then
    err "$name: $src is a link, not a folder: not copied"
    return
  fi
  if [ ! -d "$src" ]; then
    err "$name: $src is missing, mirror left untouched"
    return
  fi
  if [ -z "$(ls -A "$src" 2>/dev/null)" ] && [ -n "$(ls -A "$dst" 2>/dev/null)" ]; then
    err "$name: $src is EMPTY but the copy is not. Mirror left untouched: if that is right, empty $dst by hand."
    return
  fi
  mkdir -p "$dst" || {
    err "$name: cannot create $dst"
    return
  }
  rsync -a --delete --backup --backup-dir="$usb/deleted/$stamp/$name" "$src/" "$dst/" ||
    err "$name: rsync ended with $?"
}
if is_yes MODULE_IMMICH; then
  for part in upload library profile; do
    # library/ exists only once Immich's storage template is switched on
    [ "$part" = library ] && [ ! -d "$DATA_DIR/immich/library/$part" ] && continue
    mirror "immich-$part" "$DATA_DIR/immich/library/$part" "$usb/immich/$part"
  done
fi
mirror nas "$DATA_DIR/nas" "$usb/nas"
find "$usb/deleted" -mindepth 1 -maxdepth 1 -type d -mtime +"$deleted_keep" -exec rm -rf {} + 2>/dev/null

sync
use=$(df -Ph "$usb" 2>/dev/null | awk 'NR == 2 { print $3 " used, " $4 " free" }')
finish "copy up to date ($use)"
